const base = $('정규화·대응 계획').first().json;
const resp = $input.first().json || {};
let ai = {};
try {
  const content = resp.choices?.[0]?.message?.content || '{}';
  ai = JSON.parse(content);
} catch (e) {
  ai = { threat_score: 0, verdict: 'ERROR', reasoning: 'AI 응답 파싱 실패: ' + e.message };
}
const now = new Date();
const kstHour = Number(new Intl.DateTimeFormat('en-US', { timeZone: 'Asia/Seoul', hour: 'numeric', hourCycle: 'h23' }).format(now));
const isDaytime = kstHour >= 8 && kstHour < 20;
const threatScore = Number.isFinite(Number(ai.threat_score)) ? Number(ai.threat_score) : 0;
const autoLive = !isDaytime && threatScore >= 80;
return [{ json: { ...base,
  ai_assessment: ai, ai_threat_score: threatScore, ai_verdict: ai.verdict || 'UNKNOWN',
  kst_hour: kstHour, is_daytime: isDaytime,
  response_mode: autoLive ? 'live' : 'dry-run', live_enabled: autoLive,
  pending_approval: isDaytime && base.auto_response_allowed === true
} }];
